UPDATE equipment_items 
SET description = REPLACE(
  REPLACE(
    REPLACE(
      REPLACE(
        REPLACE(
          REPLACE(description, 'Hong Kong flat', 'flat'),
          'Hong Kong workshop', 'workshop'
        ),
        'Hong Kong terrain', 'terrain'
      ),
      'Hong Kong worksites', 'worksites'
    ),
    'Hong Kong surfaces', 'surfaces'
  ),
  'Hong Kong', ''
)
WHERE description LIKE '%Hong Kong%';

